## Enemy AI

### Patrol Enemy

```csharp
using UnityEngine;

public class PatrolEnemy : MonoBehaviour
{
    [SerializeField] private float speed = 2f;
    [SerializeField] private Transform[] waypoints;
    [SerializeField] private float waitTime = 1f;

    private int currentWaypoint = 0;
    private float waitCounter;
    private bool waiting;
    private SpriteRenderer spriteRenderer;

    void Start()
    {
        spriteRenderer = GetComponent<SpriteRenderer>();
    }

    void Update()
    {
        if (waypoints.Length == 0) return;

        if (waiting)
        {
            waitCounter -= Time.deltaTime;
            if (waitCounter <= 0)
                waiting = false;
            return;
        }

        Transform target = waypoints[currentWaypoint];
        transform.position = Vector2.MoveTowards(
            transform.position,
            target.position,
            speed * Time.deltaTime
        );

        // Flip sprite
        spriteRenderer.flipX = target.position.x < transform.position.x;

        // Reached waypoint
        if (Vector2.Distance(transform.position, target.position) < 0.1f)
        {
            currentWaypoint = (currentWaypoint + 1) % waypoints.Length;
            waiting = true;
            waitCounter = waitTime;
        }
    }
}
```

### Chase Enemy

```csharp
public class ChaseEnemy : MonoBehaviour
{
    [SerializeField] private float speed = 3f;
    [SerializeField] private float detectionRange = 5f;
    [SerializeField] private LayerMask playerLayer;

    private Transform player;
    private bool isChasing;

    void Update()
    {
        // Detect player
        Collider2D detected = Physics2D.OverlapCircle(
            transform.position, 
            detectionRange, 
            playerLayer
        );

        if (detected != null)
        {
            player = detected.transform;
            isChasing = true;
        }

        if (isChasing && player != null)
        {
            // Chase player
            Vector2 direction = (player.position - transform.position).normalized;
            transform.position += (Vector3)direction * speed * Time.deltaTime;
        }
    }
}
```

## Collectibles & Items

```csharp
public class Collectible : MonoBehaviour
{
    [SerializeField] private int points = 10;
    [SerializeField] private AudioClip collectSound;
    [SerializeField] private GameObject collectEffect;

    void OnTriggerEnter2D(Collider2D other)
    {
        if (other.CompareTag("Player"))
        {
            // Add points
            GameManager.Instance.AddScore(points);

            // Play sound
            if (collectSound != null)
                AudioSource.PlayClipAtPoint(collectSound, transform.position);

            // Spawn effect
            if (collectEffect != null)
                Instantiate(collectEffect, transform.position, Quaternion.identity);

            Destroy(gameObject);
        }
    }
}
```

## Game Manager (Singleton)

```csharp
public class GameManager : MonoBehaviour
{
    public static GameManager Instance { get; private set; }

    [SerializeField] private int lives = 3;
    private int score = 0;

    public int Score => score;
    public int Lives => lives;

    public event System.Action<int> OnScoreChanged;
    public event System.Action<int> OnLivesChanged;

    void Awake()
    {
        if (Instance == null)
        {
            Instance = this;
            DontDestroyOnLoad(gameObject);
        }
        else
        {
            Destroy(gameObject);
        }
    }

    public void AddScore(int points)
    {
        score += points;
        OnScoreChanged?.Invoke(score);
    }

    public void LoseLife()
    {
        lives--;
        OnLivesChanged?.Invoke(lives);

        if (lives <= 0)
            GameOver();
    }

    void GameOver()
    {
        Debug.Log("Game Over!");
        // Load game over scene
    }
}
```

## UI System

```csharp
using UnityEngine;
using UnityEngine.UI;
using TMPro;

public class UIManager : MonoBehaviour
{
    [SerializeField] private TextMeshProUGUI scoreText;
    [SerializeField] private TextMeshProUGUI livesText;

    void Start()
    {
        GameManager.Instance.OnScoreChanged += UpdateScore;
        GameManager.Instance.OnLivesChanged += UpdateLives;

        UpdateScore(GameManager.Instance.Score);
        UpdateLives(GameManager.Instance.Lives);
    }

    void UpdateScore(int score)
    {
        scoreText.text = $"Score: {score}";
    }

    void UpdateLives(int lives)
    {
        livesText.text = $"Lives: {lives}";
    }
}
```

## Audio Manager

```csharp
public class AudioManager : MonoBehaviour
{
    public static AudioManager Instance { get; private set; }

    [SerializeField] private AudioSource musicSource;
    [SerializeField] private AudioSource sfxSource;

    void Awake()
    {
        if (Instance == null)
        {
            Instance = this;
            DontDestroyOnLoad(gameObject);
        }
        else
        {
            Destroy(gameObject);
        }
    }

    public void PlaySFX(AudioClip clip)
    {
        sfxSource.PlayOneShot(clip);
    }

    public void PlayMusic(AudioClip clip)
    {
        musicSource.clip = clip;
        musicSource.Play();
    }
}
```

## Best Practices

### Organization

```
Assets/
├── _Scenes/         # Underscore for top of list
├── Scripts/
│   ├── Player/
│   ├── Enemies/
│   ├── Managers/
│   └── UI/
├── Art/
│   ├── Characters/
│   ├── Environment/
│   └── UI/
├── Audio/
│   ├── Music/
│   └── SFX/
├── Prefabs/
└── Animations/
```

### Performance Tips

1. ✅ Use object pooling for bullets/particles
2. ✅ Cache component references in Start()
3. ✅ Use FixedUpdate for physics
4. ✅ Limit GetComponent calls
5. ✅ Use Sprite Atlases

## Summary

1. ✅ Set up proper 2D project
2. ✅ Create responsive player controller
3. ✅ Build animation state machine
4. ✅ Use tilemaps for levels
5. ✅ Implement enemy AI
6. ✅ Add polish (audio, particles, UI)

## Conclusion

Unity makes 2D game development accessible. Start simple, iterate, and gradually add complexity as you learn.

Happy game making!
